// datos reales propios) — hoy Orison (id 6) comparte el mismo page_id de
// Facebook que Crating Express (ver CLAUDE.md, hallazgo del 13-jul, decisión
// explícita del 07-sep de excluirla hasta que tenga sus propias redes).
const EXCLUIDAS = [6];

const empresasResp = await this.helpers.httpRequest({
  method: "GET",
  url: BASE + "/api/n8n/companies?activas=1&con_redes=1",
  headers: { Authorization: "Bearer " + AGENT_TOKEN, Accept: "application/json" },
  json: true,
});
const empresas = (empresasResp && empresasResp.data) || [];

const salida = [];
for (const emp of empresas) {
  if (EXCLUIDAS.includes(emp.id)) continue;

  let targets = [];
  try {
    const tResp = await this.helpers.httpRequest({
      method: "GET",
      url: BASE + "/api/agent/companies/" + emp.id + "/social-targets",
      headers: { Authorization: "Bearer " + AGENT_TOKEN, Accept: "application/json" },
      json: true,
    });
    targets = (tResp && tResp.data) || [];
  } catch (e) {
    continue; // empresa sin conexión resuelta - se salta, no se inventa nada
  }

  const fb = targets.find(t => t.platform === "Facebook" && t.listo);
  const ig = targets.find(t => t.platform === "Instagram" && t.listo);

  if (!fb && !ig) continue; // ninguna red lista - nada real que reportar

  salida.push({
    json: {
      company_id: emp.id,
      fb_page_id: fb ? fb.page_id : null,
      ig_user_id: ig ? ig.instagram_account_id : null,
    },
  });
}

return salida;

