const fb = { alcance: 0, impresiones: 0, engagement: 0, clics: 0, reacciones: 0, compartidos: 0, comentarios: 0,
             visitas_perfil: 0, seguidores_nuevos: 0, guardados: 0, posts: 0 };
if (PAGE && PT) {
  const r = await get(PAGE + '/published_posts', {
    since: periodStart, until: periodEnd, limit: 100,
    fields: 'id,created_time,shares,insights.metric(post_total_media_view_unique,post_media_view,post_reactions_by_type_total,post_clicks_by_type,post_activity_by_action_type)'
  });
  const posts = (r && r.data) || [];
  fb.posts = posts.length;
  for (const p of posts) {
    const ins = (p.insights && p.insights.data) || [];
    const val = name => {
      const vals = ins.filter(i => i.name === name).map(i => (i.values && i.values[0]) ? i.values[0].value : 0);
      return vals.length ? Math.max(...vals.map(sumObj)) : 0;
    };
    const act = (ins.find(i => i.name === 'post_activity_by_action_type') || {}).values;
    const acts = (act && act[0] && act[0].value) || {};
    fb.alcance += val('post_total_media_view_unique');
    fb.impresiones += val('post_media_view');
    fb.reacciones += val('post_reactions_by_type_total');
    fb.clics += val('post_clicks_by_type');
    fb.comentarios += Number(acts.comment) || 0;
    fb.compartidos += (p.shares && p.shares.count) || Number(acts.share) || 0;
  }
  fb.engagement = fb.reacciones + fb.clics + fb.comentarios + fb.compartidos;
  // Nivel página: visitas y seguidores nuevos de la semana
  const pg = await get(PAGE + '/insights', { metric: 'page_views_total,page_daily_follows_unique', period: 'day', since: periodStart, until: periodEnd });
  for (const m of ((pg && pg.data) || [])) {
    const s = (m.values || []).reduce((a, v) => a + (Number(v.value) || 0), 0);
    if (m.name === 'page_views_total') fb.visitas_perfil = s;
    if (m.name === 'page_daily_follows_unique') fb.seguidores_nuevos = s;
  }
}

// ---------- Instagram: métricas de cuenta de la semana ----------
const ig = { alcance: 0, impresiones: 0, engagement: 0, clics: 0, guardados: 0, compartidos: 0,
             visitas_perfil: 0, seguidores_nuevos: 0, profile_views: 0 };
if (IGID && PT) {
  const r = await get(IGID + '/insights', {
    metric: 'reach,views,total_interactions,saves,shares,profile_views,website_clicks',
    metric_type: 'total_value', period: 'day', since: periodStart, until: periodEnd
  });
  const v = name => { const m = ((r && r.data) || []).find(x => x.name === name); return (m && m.total_value && Number(m.total_value.value)) || 0; };
  ig.alcance = v('reach'); ig.impresiones = v('views'); ig.engagement = v('total_interactions');
  ig.guardados = v('saves'); ig.compartidos = v('shares'); ig.clics = v('website_clicks');
  ig.visitas_perfil = v('profile_views'); ig.profile_views = ig.visitas_perfil;
  // follower_count solo lo da Meta con 100+ seguidores; si no viene, queda 0 (no se inventa).
  const f = await get(IGID + '/insights', { metric: 'follower_count', period: 'day', since: periodStart, until: periodEnd });
  const fc = ((f && f.data) || [])[0];
  if (fc) ig.seguidores_nuevos = (fc.values || []).reduce((a, x) => a + (Number(x.value) || 0), 0);
}

const rate = (e, a) => a > 0 ? parseFloat((e / a * 100).toFixed(2)) : 0;
return [{ json: {
  period_start: periodStart,
  period_end: periodEnd,
  fb, ig,
  engagement_rate_fb: rate(fb.engagement, fb.alcance),
  engagement_rate_ig: rate(ig.engagement, ig.alcance),
  engagement_rate: rate(fb.engagement, fb.alcance)
} }];

const query = $('🌐 Trigger Webhook').item.json.query || {};
const body  = $('🌐 Trigger Webhook').item.json.body  || {};
const postId    = query.post_id    || body.post_id;
const companyId = query.company_id || body.company_id || $('⚙️ Config Growth54').item.json.G54_COMPANY_ID;

const insData = $('📊 Meta API: Post Insights').item?.json?.data || [];

const getVal = (name) => insData.find(i => i.name === name)?.values?.[0]?.value || 0;
const getObjSum = (name) => {
  const v = insData.find(i => i.name === name)?.values?.[0]?.value;
  if (!v) return 0;
  if (typeof v === 'object') return Object.values(v).reduce((a,b) => a+b, 0);
  return v;
};

const alcance    = getVal('post_fan_reach');
const reacciones = getVal('post_reactions_like_total');
const clics      = getObjSum('post_clicks_by_type');
const engagement = reacciones + clics;
const engRate    = alcance > 0 ? parseFloat((engagement / alcance * 100).toFixed(2)) : 0;
const today      = new Date().toISOString().slice(0,10);

return [{
  json: {
    company_id: parseInt(companyId) || 1,
    post_id: postId,
    platform: String(postId).includes('_') ? 'facebook' : 'instagram',
    period_start: today,
    period_end: today,
    alcance_total: alcance,
    impresiones_total: alcance,
    engagement_total: engagement,
    engagement_rate_avg: engRate,
    clics_total: clics,
    leads_total: 0
  }
}];

